/**
 * 2026-09-06: plain text line, not a banner -- was a colored `Surface` pill with an icon; removed
 * in favor of matching the same plain-caption "Analyzed as of" treatment `DetailHeader`'s own
 * `analyzedAsOfTimestamp` line and the shared `AnalyzedAtHeader` use elsewhere (`labelSmall`/
 * `onSurfaceMuted`, no icon, no colored container) -- this screen doesn't need its own more
 * prominent chrome for what's fundamentally the same "here's when this was last updated" fact
 * every other screen states plainly. Distinct from the compact [DeepDiveLabel] used on the preview
 * card and atop [DeepDiveCard]: this is the one place the authoritative `deep_analysis_date` (with
 * year, since nothing else on this dedicated screen already establishes the year) and
 * `next_deep_dive_trigger_reason` ("biweekly"/"earnings", free-form per the backend -- same
 * treatment as `technicalSetup` elsewhere in this app, not a fixed enum) are both shown together.
 * Same cold-start rule as [deepDiveDisplayParts]: both dates null renders nothing.
 *
 * Parts are joined via the shared bigger-bullet helper rather than a plain string concatenation --
 * the "NEXT: ..." half is already pre-uppercased in its own string resource, and the interpolated
 * date must stay natural case ("Updated as of Sep 4, 2026", not "...SEP 4, 2026"). Own parts (not
 * [deepDiveDisplayParts]) since this is the one touchpoint using the with-year date format, and the
 * one place the "available" label reads "Updated as of ..." (sentence case, no "DEEP DIVE
 * AVAILABLE" -- this screen already establishes "this is the Deep Dive" by being it).
 */
@Composable
fun DeepDiveUpdatedAtLine(
    deepAnalysisDate: String?,
    nextDeepDiveTriggerDate: String?,
    nextDeepDiveTriggerReason: String?,
    modifier: Modifier = Modifier
) {
    if (deepAnalysisDate == null && nextDeepDiveTriggerDate == null) return
    val pulseColors = LocalPulseColors.current

    val datedPart = deepAnalysisDate?.let {
        stringResource(id = R.string.stock_detail_deep_dive_updated_as_of, it.toShortDateWithYearString())
    }
    val nextPart = nextDeepDiveTriggerDate?.let {
        val nextRes = if (deepAnalysisDate == null) R.string.stock_detail_deep_dive_next_standalone else R.string.stock_detail_deep_dive_next
        stringResource(id = nextRes, it.toShortDateString())
    }
    val reasonSuffix = nextDeepDiveTriggerReason?.let { " ($it)" }.orEmpty()

    Text(
        text = buildBulletJoinedText(
            parts = listOfNotNull(datedPart, nextPart?.plus(reasonSuffix)),
            bullet = stringResource(id = R.string.bullet_separator),
            baseFontSize = MaterialTheme.typography.labelSmall.fontSize
        ),
        style = MaterialTheme.typography.labelSmall,
        color = pulseColors.onSurfaceMuted,
        modifier = modifier
    )
}

